import{_ as o,o as a,c as r,aN as l}from"./chunks/framework.D31DlcCL.js";const g=JSON.parse('{"title":"从凌绝顶到国破山河：杜甫的诗史蜕变与家国情怀","description":"","frontmatter":{"title":"从凌绝顶到国破山河：杜甫的诗史蜕变与家国情怀","date":"2023-12-15T00:00:00.000Z","categories":["历史人物","杂谈"],"tags":["杜甫","诗史","家国情怀"]},"headers":[],"relativePath":"posts/du-fu-analysis.md","filePath":"posts/du-fu-analysis.md","lastUpdated":null}'),p={name:"posts/du-fu-analysis.md"};function i(e,t,s,n,u,h){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="大唐第一-苦情-顶流-杜甫的诗史炼成与家国残梦" tabindex="-1">大唐第一&quot;苦情&quot;顶流：杜甫的诗史炼成与家国残梦 <a class="header-anchor" href="#大唐第一-苦情-顶流-杜甫的诗史炼成与家国残梦" aria-label="Permalink to &quot;大唐第一&quot;苦情&quot;顶流：杜甫的诗史炼成与家国残梦&quot;">​</a></h1><p><img src="https://images.unsplash.com/photo-1542332213-31f87348057f?q=80&amp;w=1000&amp;auto=format&amp;fit=crop" alt="杜甫像：时代的背影"><em>图1：那是一个时代的脊梁，在最深重的苦难中，用笔墨记录了一个帝国的崩塌与重生。</em></p><h2 id="序章-历史的分水岭" tabindex="-1">序章：历史的分水岭 <a class="header-anchor" href="#序章-历史的分水岭" aria-label="Permalink to &quot;序章：历史的分水岭&quot;">​</a></h2><p>长安，天宝十四年（755年）十一月初九。</p><p>一个看似平常的冬日，却成为大唐帝国的转折点。安禄山以&quot;清君侧&quot;为名，在范阳发动叛乱，八千铁骑如黑色潮水般向南涌来。消息传到长安时，唐玄宗正在华清池享受温泉水滑，杨贵妃正在霓裳羽衣曲中翩翩起舞。</p><p>而远在奉先县（今陕西蒲城）的杜甫，刚刚写完《自京赴奉先县咏怀五百字》。在这首长诗中，他写道：&quot;朱门酒肉臭，路有冻死骨。&quot;这句诗如同预言，道出了盛唐繁华背后的社会矛盾。</p><p>杜甫，字子美，生于公元712年，卒于770年。他的一生横跨了唐代最辉煌的时期，也经历了最动荡的年代。从&quot;会当凌绝顶&quot;的壮游少年，到&quot;国破山河在&quot;的诗史巨匠，杜甫的人生轨迹与中国历史的走向惊人地重合。</p><p>&quot;诗史&quot;——这是后世对杜甫的评价，但这个称号背后，是一个普通人如何在历史洪流中挣扎、思考、最终成为文化符号的复杂过程。杜甫的诗歌不仅仅是历史的记录，更是一个灵魂对时代的深刻回应。</p><h2 id="第一章-家世与少年时代" tabindex="-1">第一章：家世与少年时代 <a class="header-anchor" href="#第一章-家世与少年时代" aria-label="Permalink to &quot;第一章：家世与少年时代&quot;">​</a></h2><p>杜甫出身于一个没落的官僚家庭。他的十三世祖杜预是西晋的名将，精通《左传》，被誉为&quot;杜武库&quot;。杜甫的父亲杜闲曾任奉天（今陕西乾县）县令，属于中层官僚。</p><p><img src="https://images.unsplash.com/photo-1544084944-15269ec7b5a0?q=80&amp;w=1000&amp;auto=format&amp;fit=crop" alt="少年壮游：泰山的绝顶"><em>图2：开元盛世的余晖中，少年杜甫正登上泰山，那时的他，心中只有&quot;一览众山小&quot;的壮志。</em></p><p>家世的双重性——既有显赫的祖先，又有现实的没落——成为杜甫一生的精神底色。这种双重性使他在面对社会现实时，既有一种贵族的责任感，又有一种平民的同情心。</p><p>开元十九年（731年），二十岁的杜甫开始了他的壮游生涯。他先是游历吴越，后来又到齐赵（今山东河北一带）一带游历。这段时间的游历对杜甫的人生观和诗歌创作产生了深远影响。</p><p>&quot;会当凌绝顶，一览众山小。&quot;</p><p>《望岳》这首诗写于杜甫游历泰山时。表面上是写泰山的雄伟，实际上是表达了青年杜甫的豪情壮志。这种&quot;凌绝顶&quot;的气概，体现了盛唐文人的精神风貌——自信、豪迈、充满进取精神。</p><p>杜甫的少年时代，正值唐玄宗开元盛世的巅峰时期。这个时代的特征是：政治相对清明，经济繁荣发展，文化昌盛发达，对外交流频繁。在这样的时代背景下，杜甫形成了积极入世的人生态度。</p><p>&quot;读书破万卷，下笔如有神。&quot;</p><p>杜甫的这句诗，反映了他对学问的执着追求。在唐代，读书入仕是知识分子的主要出路。杜甫也不例外，他希望通过科举考试进入仕途，实现自己的政治理想。</p><h2 id="第二章-长安十年-仕途的坎坷" tabindex="-1">第二章：长安十年：仕途的坎坷 <a class="header-anchor" href="#第二章-长安十年-仕途的坎坷" aria-label="Permalink to &quot;第二章：长安十年：仕途的坎坷&quot;">​</a></h2><p>天宝五年（746年），三十五岁的杜甫来到长安，开始了他的&quot;长安十年&quot;。这十年是杜甫人生中最艰难的时期，也是他诗歌创作的重要阶段。</p><p>在长安，杜甫经历了多次科举考试，但都未能成功。唐代的科举制度虽然相对公平，但也存在着诸多不公因素。杜甫的落第，既有个人能力的原因，也有社会环境的因素。</p><p>&quot;朝扣富儿门，暮随肥马尘。残杯与冷炙，到处潜悲辛。&quot;</p><p>《奉赠韦左丞丈二十二韵》中的这几句诗，真实地反映了杜甫在长安的艰难处境。为了生计，他不得不依附于权贵门下，过着寄人篱下的生活。这种经历使他对社会底层人民的苦难有了更深刻的理解。</p><p>天宝十四年（755年），杜甫终于得到了一个右卫率府胄曹参军的职位，负责管理兵器。这是一个从八品的小官，俸禄微薄，地位低下。但杜甫对这个职位仍然充满期待，因为这毕竟是他踏入仕途的第一步。</p><p>&quot;不谓黔娄有此妻，亦知扬雄非难攀。&quot;</p><p>杜甫在《同诸公登慈恩寺塔》中表达了对仕途的期待。黔娄是古代的贫士，扬雄是西汉的文学家，杜甫用这两个典故来表达自己虽然出身不高，但仍然希望通过努力获得成功的决心。</p><p>然而，就在杜甫刚刚获得职位不久，安史之乱爆发了。这场突如其来的战乱，不仅改变了大唐的命运，也彻底改变了杜甫的人生轨迹。</p><h2 id="第三章-安史之乱-乱世中的挣扎" tabindex="-1">第三章：安史之乱：乱世中的挣扎 <a class="header-anchor" href="#第三章-安史之乱-乱世中的挣扎" aria-label="Permalink to &quot;第三章：安史之乱：乱世中的挣扎&quot;">​</a></h2><p>安史之乱（755-763年）是唐代历史的转折点，也是杜甫人生的重大转折点。在这场持续八年的战乱中，杜甫经历了流离失所、饥寒交迫的苦难，这些经历深刻地影响了他的诗歌创作。</p><p>杜甫在安史之乱中的经历，可以用&quot;逃难&quot;两个字来概括。从长安到鄜州（今陕西富县），从鄜州到羌村（今陕西耀县），从羌村到秦州（今甘肃天水），从秦州到同谷（今甘肃成县），从同谷到成都，杜甫的逃难路线几乎覆盖了大半个中国。</p><p>&quot;国破山河在，城春草木深。感时花溅泪，恨别鸟惊心。&quot;</p><p>《春望》这首诗写于安史之乱期间，当时杜甫被困在长安。诗中表达了他对国家命运的忧虑和对家人的思念。&quot;国破山河在&quot;一句，道出了杜甫对家国情怀的深刻理解——即使国家破碎，山河依然存在，这种永恒的自然成为乱世中人们的精神寄托。</p><p>&quot;烽火连三月，家书抵万金。白头搔更短，浑欲不胜簪。&quot;</p><p>《春望》中的这两句诗，真实地反映了战争年代人们的生存状态。在战火中，家书变得无比珍贵；在忧虑中，人们迅速衰老。杜甫通过具体的细节描写，展现了战争的残酷和人民的苦难。</p><p>杜甫在安史之乱中的经历，使他的诗歌风格发生了重大转变。从早期的豪迈奔放，中期的沉郁顿挫，到后期的悲悯深沉，杜甫的诗歌风格与他的人生经历密切相关。</p><h2 id="第四章-入蜀与漂泊-生命的最后阶段" tabindex="-1">第四章：入蜀与漂泊：生命的最后阶段 <a class="header-anchor" href="#第四章-入蜀与漂泊-生命的最后阶段" aria-label="Permalink to &quot;第四章：入蜀与漂泊：生命的最后阶段&quot;">​</a></h2><p><img src="https://images.unsplash.com/photo-1528164344705-4754268799af?q=80&amp;w=1000&amp;auto=format&amp;fit=crop" alt="成都草堂：乱世中的片刻宁静"><em>图3：浣花溪畔的草堂，是杜甫一生中难得的避风港，也是《绝句》与《秋兴》的诞生地。</em></p><p>乾元二年（759年），杜甫来到成都，在朋友严武的帮助下，修建了草堂。这是杜甫一生中相对稳定的时期，也是他诗歌创作的丰收期。</p><p>&quot;两个黄鹂鸣翠柳，一行白鹭上青天。窗含西岭千秋雪，门泊东吴万里船。&quot;</p><p>《绝句四首》其三这首诗，写于杜甫在成都草堂时期。诗中描绘了一幅宁静祥和的画面，体现了杜甫在相对稳定的生活中对美好事物的欣赏。然而，这种宁静只是暂时的，杜甫的一生始终处于漂泊状态。</p><p>宝应元年（762年），严武去世，杜甫失去了在成都的依靠，不得不再次漂泊。他从成都到梓州（今四川三台），再到阆中（今四川阆中），最后又回到成都。这种漂泊的生活使杜甫的身体状况日益恶化。</p><p>&quot;无边落木萧萧下，不尽长江滚滚来。万里悲秋常作客，百年多病独登台。&quot;</p><p>《登高》这首诗写于杜甫晚年，诗中表达了他对生命的深刻思考。无边落木象征生命的凋零，不尽长江象征时间的流逝，百年多病象征身体的衰败。杜甫通过这些意象，表达了对生命本质的思考。</p><p>杜甫晚年的诗歌，充满了对生命的深刻思考和对社会的深切关怀。即使身体衰弱，他仍然关注着国家的命运和人民的苦难。</p><p>&quot;安得广厦千万间，大庇天下寒士俱欢颜！&quot;</p><p>《茅屋为秋风所破歌》中的这句诗，体现了杜甫的博大胸怀。即使自己处于贫困潦倒的境地，杜甫仍然关心着天下寒士的生存状况。这种胸怀使他成为中国历史上最伟大的诗人之一。</p><h2 id="第五章-诗歌文本的意象解码" tabindex="-1">第五章：诗歌文本的意象解码 <a class="header-anchor" href="#第五章-诗歌文本的意象解码" aria-label="Permalink to &quot;第五章：诗歌文本的意象解码&quot;">​</a></h2><p><img src="https://images.unsplash.com/photo-1501785888041-af3ef285b470?q=80&amp;w=1000&amp;auto=format&amp;fit=crop" alt="滚滚长江：晚年的悲怆"><em>图4：三峡的急流与猿鸣，是杜甫晚年最悲凉的背景音乐。</em></p><p>杜甫的诗歌之所以被称为&quot;诗史&quot;，不仅是因为他的诗歌记录了历史事实，更是因为他的诗歌具有丰富的意象和深刻的思想内涵。</p><p>杜甫诗歌中的意象可以分为几类：自然意象、社会意象、历史意象、情感意象。这些意象相互交织，构成了杜甫诗歌的独特艺术魅力。</p><p>&quot;风急天高猿啸哀，渚清沙白鸟飞回。无边落木萧萧下，不尽长江滚滚来。&quot;</p><p>《登高》这首诗中的意象，体现了杜甫诗歌的特点。风、天、猿、渚、沙、鸟、落木、长江，这些自然意象相互呼应，构成了一幅壮阔而凄美的画面。这些意象不仅仅是客观描写，更是诗人内心世界的投射。</p><p>杜甫诗歌中的社会意象，主要是对战争、贫困、社会不公等现象的描写。&quot;朱门酒肉臭，路有冻死骨&quot;这句诗，通过对社会现实的对比描写，表达了杜甫对社会不公的深刻批判。</p><p>杜甫诗歌中的历史意象，主要是对历史变迁的思考。&quot;国破山河在，城春草木深&quot;这句诗，通过对历史变迁的描写，表达了杜甫对历史规律的深刻理解。</p><p>杜甫诗歌中的情感意象，主要是对个人情感的抒发。&quot;感时花溅泪，恨别鸟惊心&quot;这句诗，通过对个人情感的描写，表达了杜甫对时代变迁的深刻感受。</p><p>杜甫诗歌的意象特点，可以用&quot;沉郁顿挫&quot;四个字来概括。沉郁是指诗歌的情感基调深沉而忧郁，顿挫是指诗歌的语言节奏起伏变化。这种特点使杜甫的诗歌具有强烈的艺术感染力。</p><h2 id="第六章-仕途经济与艺术追求的矛盾" tabindex="-1">第六章：仕途经济与艺术追求的矛盾 <a class="header-anchor" href="#第六章-仕途经济与艺术追求的矛盾" aria-label="Permalink to &quot;第六章：仕途经济与艺术追求的矛盾&quot;">​</a></h2><p>杜甫的一生，始终面临着仕途经济与艺术追求的矛盾。这种矛盾反映了古代知识分子的普遍困境：如何在现实社会中生存，又如何保持艺术上的纯粹性。</p><p>杜甫的仕途经历可以分为几个阶段：早期是科举考试阶段，中期是做官阶段，后期是漂泊阶段。在每个阶段，杜甫都面临着不同的经济压力和艺术追求的冲突。</p><p>&quot;致君尧舜上，再使风俗淳。&quot;</p><p>杜甫在《奉赠韦左丞丈二十二韵》中表达了自己的政治理想。他希望通过自己的政治才能，使君主成为尧舜那样的圣君，使社会风气变得淳朴。这种政治理想，是杜甫仕途追求的动力来源。</p><p>然而，现实中的仕途却充满了挫折和失望。杜甫多次科举考试都未能成功，即使做官也只是个小官。这种仕途的不顺，使杜甫对现实社会产生了深刻的怀疑和批判。</p><p>&quot;朱门酒肉臭，路有冻死骨。&quot;</p><p>这句诗体现了杜甫对社会现实的深刻批判。他看到的是社会的两极分化：权贵阶层过着奢靡的生活，而底层人民却在饥寒交迫中挣扎。这种批判，反映了杜甫对社会现实的清醒认识。</p><p>杜甫的经济困境，主要体现在以下几个方面：科举考试的费用、做官的俸禄、漂泊的生活费用。这些经济压力，使杜甫不得不在艺术追求和现实生活之间寻找平衡。</p><p>杜甫的艺术追求，主要体现在对诗歌艺术的不断探索和创新上。他不仅继承了前人的诗歌传统，还开创了新的诗歌风格和表现手法。这种艺术追求，使杜甫成为中国诗歌史上的重要人物。</p><p>杜甫的仕途经济与艺术追求的矛盾，反映了中国古代知识分子的普遍困境。这种矛盾既是杜甫个人的悲剧，也是中国文学史上的重要财富。</p><h2 id="第七章-后世文化符号的生成" tabindex="-1">第七章：后世文化符号的生成 <a class="header-anchor" href="#第七章-后世文化符号的生成" aria-label="Permalink to &quot;第七章：后世文化符号的生成&quot;">​</a></h2><p>杜甫在后世文化符号的生成，是一个复杂的历史过程。从唐代到现代，杜甫的形象一直在不断地被重新诠释和构建。</p><p>在唐代，杜甫主要被视为一个成功的诗人和一个失意的官员。他的诗歌虽然受到一定重视，但还没有达到&quot;诗圣&quot;的地位。杜甫的&quot;诗圣&quot;地位是在宋代逐渐确立的。</p><p>在宋代，随着理学的兴起，杜甫的&quot;诗圣&quot;地位逐渐确立。理学家们认为杜甫的诗歌体现了儒家思想的核心——仁爱和关怀。这种评价使杜甫成为中国诗歌史上的重要人物。</p><p>&quot;诗史&quot;——这是宋代文人对杜甫的评价。这个评价不仅肯定了杜甫诗歌的历史价值，还肯定了杜甫诗歌的思想价值。杜甫的诗歌确实记录了安史之乱等重要历史事件，也表达了对社会现实的深刻批判。</p><p>在近现代，杜甫的形象进一步丰富。随着中国社会的发展，杜甫被视为中国知识分子的典范——关心国家命运，关注社会现实，具有强烈的社会责任感。</p><p>&quot;诗圣&quot;、&quot;诗史&quot;、&quot;人民诗人&quot;——这些称号构成了杜甫文化符号的核心。这些称号不仅是对杜甫诗歌成就的肯定，也是对杜甫人格精神的肯定。</p><p>杜甫的文化符号生成，还体现在他的诗歌对后世的影响上。杜甫的诗歌对后世的中国文学、艺术、思想等方面都产生了深远影响。他的诗歌不仅是文学遗产，更是文化遗产。</p><h2 id="第八章-人物与时代的互文关系" tabindex="-1">第八章：人物与时代的互文关系 <a class="header-anchor" href="#第八章-人物与时代的互文关系" aria-label="Permalink to &quot;第八章：人物与时代的互文关系&quot;">​</a></h2><p>杜甫的一生与中国历史的走向惊人地重合。他经历了盛唐的繁华，也经历了安史之乱的动荡，他的诗歌记录了这段历史，也回应了这段历史。</p><p>杜甫与时代的互文关系，主要体现在以下几个方面：杜甫对时代的记录，时代对杜甫的影响，杜甫对时代的回应。</p><p>杜甫对时代的记录，主要体现在他的诗歌中。杜甫的诗歌记录了安史之乱等重要历史事件，也记录了当时的社会现实。这些记录不仅是历史资料，也是文学作品。</p><p>&quot;国破山河在，城春草木深。感时花溅泪，恨别鸟惊心。&quot;</p><p>《春望》这首诗，记录了安史之乱期间长安的荒凉景象。诗中表达了对国家命运的忧虑和对家人的思念。这种记录，既是对历史的客观描写，也是对历史的深刻思考。</p><p>时代对杜甫的影响，主要体现在杜甫的人生经历上。安史之乱的爆发，使杜甫经历了流离失所、饥寒交迫的苦难，这些经历深刻地影响了杜甫的诗歌创作。</p><p>杜甫对时代的回应，主要体现在他的诗歌创作上。杜甫通过诗歌来表达对时代的思考，对社会现实的批判，对人生意义的探索。这种回应，使杜甫成为中国历史上最伟大的诗人之一。</p><p>杜甫与时代的互文关系，体现了文学与历史、个人与社会、现实与理想的复杂关系。这种关系不仅是杜甫个人的特点，也是中国文学史上的重要现象。</p><h2 id="结语-诗史巨匠的永恒价值" tabindex="-1">结语：诗史巨匠的永恒价值 <a class="header-anchor" href="#结语-诗史巨匠的永恒价值" aria-label="Permalink to &quot;结语：诗史巨匠的永恒价值&quot;">​</a></h2><p>杜甫的一生，是一场在乱世中寻找精神家园的艰难旅程。他用诗歌记录了历史的变迁，用思考回应了时代的挑战，用生命诠释了知识分子的责任。</p><p>&quot;诗圣&quot;、&quot;诗史&quot;、&quot;人民诗人&quot;——这些称号不仅是对杜甫的赞美，更是对杜甫精神的理解。杜甫的诗歌不仅是文学遗产，更是文化遗产；不仅是个人情感的抒发，更是集体记忆的承载。</p><p>杜甫的诗歌告诉我们：在乱世中，要保持对正义的追求；在贫困中，要保持对美好事物的欣赏；在绝望中，要保持对希望的坚持。这种精神，正是杜甫留给我们的永恒价值。</p><p>&quot;会当凌绝顶，一览众山小&quot;——杜甫的这句诗，不仅是对泰山雄伟的描写，更是对人生境界的追求。在杜甫的一生中，他虽然经历了无数的苦难和挫折，但始终保持着对理想的追求和对人生的思考。</p><p>这就是杜甫——一个在乱世中坚守理想，在贫困中保持尊严，在绝望中寻找希望的伟大诗人。他的诗歌，将永远激励着后人去思考人生的意义，去追求美好的未来。</p><hr><h2 id="关键史料出处索引" tabindex="-1">关键史料出处索引 <a class="header-anchor" href="#关键史料出处索引" aria-label="Permalink to &quot;关键史料出处索引&quot;">​</a></h2><ol><li>《旧唐书·杜甫传》- 正史记载杜甫生平</li><li>《新唐书·杜甫传》- 补充正史记载</li><li>《唐才子传》- 唐代文人传记资料</li><li>《杜甫年谱》- 杜甫生平详细年表</li><li>《杜工部集》- 杜甫作品集</li><li>《杜诗镜铨》- 杜甫诗歌注解</li><li>《读杜心解》- 杜甫诗歌解读</li><li>《钱注杜诗》- 清代钱谦益注杜诗</li><li>《仇注杜诗》- 清代仇兆鳌注杜诗</li><li>《杨伦杜诗镜铨》- 清代杨伦注杜诗</li></ol><h2 id="杜甫重要诗歌原文及白话译文" tabindex="-1">杜甫重要诗歌原文及白话译文 <a class="header-anchor" href="#杜甫重要诗歌原文及白话译文" aria-label="Permalink to &quot;杜甫重要诗歌原文及白话译文&quot;">​</a></h2><h3 id="_1-《望岳》" tabindex="-1">1. 《望岳》 <a class="header-anchor" href="#_1-《望岳》" aria-label="Permalink to &quot;1. 《望岳》&quot;">​</a></h3><p><strong>原文：</strong> 岱宗夫如何？齐鲁青未了。 造化钟神秀，阴阳割昏晓。 荡胸生曾云，决眦入归鸟。 会当凌绝顶，一览众山小。</p><p><strong>白话译文：</strong> 泰山是什么样子？齐鲁大地上的青色连绵不绝。 大自然将神奇秀美都集中在这里，山的南北分割了昏晓。 胸怀激荡生出层层云霞，极目追踪归巢的鸟儿。 一定要登上泰山的最高峰，俯瞰群山都觉得渺小。</p><h3 id="_2-《春望》" tabindex="-1">2. 《春望》 <a class="header-anchor" href="#_2-《春望》" aria-label="Permalink to &quot;2. 《春望》&quot;">​</a></h3><p><strong>原文：</strong> 国破山河在，城春草木深。 感时花溅泪，恨别鸟惊心。 烽火连三月，家书抵万金。 白头搔更短，浑欲不胜簪。</p><p><strong>白话译文：</strong> 国家破碎但山河依然存在，春天的城里草木丛生。 感伤时事看到花都落泪，怨恨离别听到鸟都惊心。 战火连绵不断已经三个月家信珍贵得抵万金。 白发越搔越稀疏，简直插不上发簪了。</p><h3 id="_3-《登高》" tabindex="-1">3. 《登高》 <a class="header-anchor" href="#_3-《登高》" aria-label="Permalink to &quot;3. 《登高》&quot;">​</a></h3><p><strong>原文：</strong> 风急天高猿啸哀，渚清沙白鸟飞回。 无边落木萧萧下，不尽长江滚滚来。 万里悲秋常作客，百年多病独登台。 艰难苦恨繁霜鬓，潦倒新停浊酒杯。</p><p><strong>白话译文：</strong> 风急天高猿猴啼叫悲哀，小洲清澈沙滩洁白鸟儿飞回。 无边无际的落叶萧萧飘下，不尽的长江滚滚涌来。 万里悲秋常常作客他乡，百年多病独自登上高台。 艰难困苦使白发增多，潦倒新近停了浊酒杯。</p><h3 id="_4-《茅屋为秋风所破歌》" tabindex="-1">4. 《茅屋为秋风所破歌》 <a class="header-anchor" href="#_4-《茅屋为秋风所破歌》" aria-label="Permalink to &quot;4. 《茅屋为秋风所破歌》&quot;">​</a></h3><p><strong>原文：</strong> 八月秋高风怒号，卷我屋上三重茅。 茅飞渡江洒江郊，高者挂罥长林梢，下者飘转沉塘坳。 南村群童欺我老无力，忍能对面为盗贼。 公然抱茅入竹去，唇焦口燥呼不得，归来倚杖自叹息。 俄顷风定云墨色，秋天漠漠向昏黑。 布衾多年冷似铁，娇儿恶卧踏里裂。 床头屋漏无干处，雨脚如麻未断绝。 自经丧乱少睡眠，长夜沾湿何由彻！ 安得广厦千万间，大庇天下寒士俱欢颜！ 风雨不动安如山。呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！</p><p><strong>白话译文：</strong> 八月秋高风怒号，卷走我屋顶上的三层茅草。 茅草飞过江洒在江边，高的挂在树梢，低的飘落在池塘里。 南村的孩子们欺负我年老无力，竟当面做盗贼。 公然抱着茅草跑进竹林，我喊得口干舌燥也无法阻止，回来拄着拐杖叹息。 一会儿风停云黑，秋天昏暗。 布盖多年冷得像铁，孩子睡觉不好踢破了里面。 床头的房子漏水没有干的地方，雨点像麻一样没断过。 自从战乱很少睡眠，长夜潮湿怎么才能天亮！ 怎么能得到千万间大房子，天下贫寒的读书人都欢颜！ 风雨不动安稳如山。唉！什么时候眼前突然出现这样的房子，我的房子破了自己受冻死也甘心！</p><h3 id="_5-《绝句四首》其三" tabindex="-1">5. 《绝句四首》其三 <a class="header-anchor" href="#_5-《绝句四首》其三" aria-label="Permalink to &quot;5. 《绝句四首》其三&quot;">​</a></h3><p><strong>原文：</strong> 两个黄鹂鸣翠柳，一行白鹭上青天。 窗含西岭千秋雪，门泊东吴万里船。</p><p><strong>白话译文：</strong> 两只黄鹂在翠绿的柳树上鸣叫，一行白鹭飞向青天。 窗户含着西岭千秋雪，门前停泊着东吴万里船。</p><h3 id="_6-《自京赴奉先县咏怀五百字》" tabindex="-1">6. 《自京赴奉先县咏怀五百字》 <a class="header-anchor" href="#_6-《自京赴奉先县咏怀五百字》" aria-label="Permalink to &quot;6. 《自京赴奉先县咏怀五百字》&quot;">​</a></h3><p><strong>原文：</strong> 杜陵有布衣，老大意转拙。 许身一何愚，窃比稷与契。 居然成濩落，白首甘契阔。 盖棺事则已，此志常觊豁。 穷年忧黎元，叹息肠内热。 取笑同学翁，浩歌弥激烈。 非无江海志，潇洒送日月。 生逢尧舜君，不忍便永诀。 当今廊庙具，构厦岂云缺？ 葵藿倾太阳，物性固莫夺。 顾惟群蚁辈，但自求其穴。 胡为慕大鲸，辄拟偃溟渤？ 以兹误生理，独耻事干谒。 兀兀遂至今，忍为尘埃没。 终愧巢与由，未能易其节。 沉饮聊自遣，放歌破愁绝。</p><p><strong>白话译文：</strong> 杜陵有个平民，年纪大了更加笨拙。 许身报国多么愚蠢，私下里自比稷和契。 竟然这样无所成就，到老甘愿受苦。 盖棺才算结束，这个志向常常希望能够实现。 一年到头忧愁百姓，叹息内心发热。 被同辈嘲笑，放声歌唱更加激烈。 不是没有隐居的志向，也能潇洒地度过时光。 生逢尧舜那样的君主，不忍心就此告别。 当今朝廷都有栋梁，建造房屋难道还缺吗？ 葵藿向着太阳，物的本性不能改变。 只是看着那些群蚁般的人，只求自己的洞穴。 为什么羡慕大鲸鱼，想要在海洋里遨游？ 因为这个耽误了生计，独独耻于干谒奔走。 平庸到今天，忍心被尘埃淹没。 最终愧对巢父和许由，不能改变自己的节操。 沉醉酒中聊且自我排遣，放声歌唱破除愁苦。</p><h2 id="唐代官职术语表" tabindex="-1">唐代官职术语表 <a class="header-anchor" href="#唐代官职术语表" aria-label="Permalink to &quot;唐代官职术语表&quot;">​</a></h2><h3 id="_1-中央官职" tabindex="-1">1. 中央官职 <a class="header-anchor" href="#_1-中央官职" aria-label="Permalink to &quot;1. 中央官职&quot;">​</a></h3><ul><li><strong>工部</strong>：负责工程建设的部门</li><li><strong>员外郎</strong>：中央各部的副长官</li><li><strong>司功参军</strong>：负责功绩考核的官员</li><li><strong>左拾遗</strong>：谏官，负责向皇帝提建议</li><li><strong>右补阙</strong>：谏官，负责向皇帝提建议</li><li><strong>华州司功参军</strong>：华州负责功绩考核的官员</li><li><strong>剑南节度使</strong>：剑南地区的军事长官</li><li><strong>检校工部员外郎</strong>：临时担任工部员外郎的官员</li></ul><h3 id="_2-地方官职" tabindex="-1">2. 地方官职 <a class="header-anchor" href="#_2-地方官职" aria-label="Permalink to &quot;2. 地方官职&quot;">​</a></h3><ul><li><strong>县尉</strong>：县的副长官，负责治安</li><li><strong>司马</strong>：州的副长官</li><li><strong>刺史</strong>：州的长官</li><li><strong>太守</strong>：郡的长官</li><li><strong>县令</strong>：县的长官</li><li><strong>参军</strong>：州的属官</li><li><strong>主簿</strong>：负责文书工作的官员</li><li><strong>录事参军</strong>：负责文书和行政工作的官员</li></ul><h3 id="_3-临时官职" tabindex="-1">3. 临时官职 <a class="header-anchor" href="#_3-临时官职" aria-label="Permalink to &quot;3. 临时官职&quot;">​</a></h3><ul><li><strong>检校</strong>：临时担任某官职的称号</li><li><strong>行</strong>：临时担任某官职的称号</li><li><strong>守</strong>：暂时担任某官职的称号</li><li><strong>摄</strong>：代理某官职的称号</li><li><strong>兼</strong>：兼任某官职的称号</li><li><strong>判</strong>：负责某项工作的官员</li><li><strong>知</strong>：主持某项工作的官员</li></ul><h3 id="_4-荣誉性官职" tabindex="-1">4. 荣誉性官职 <a class="header-anchor" href="#_4-荣誉性官职" aria-label="Permalink to &quot;4. 荣誉性官职&quot;">​</a></h3><ul><li><strong>工部员外郎</strong>：工部的副长官</li><li><strong>翰林学士</strong>：皇帝的文学侍从</li><li><strong>侍读</strong>：为皇帝讲学的官员</li><li><strong>侍讲</strong>：为皇帝讲解经书的官员</li><li><strong>右司郎中</strong>：尚书省官员，负责行政事务</li><li><strong>左司郎中</strong>：尚书省官员，负责行政事务</li></ul><h3 id="_5-其他官职" tabindex="-1">5. 其他官职 <a class="header-anchor" href="#_5-其他官职" aria-label="Permalink to &quot;5. 其他官职&quot;">​</a></h3><ul><li><strong>御史</strong>：负责监察的官员</li><li><strong>殿中侍御史</strong>：在朝堂上监察百官的官员</li><li><strong>监察御史</strong>：负责监察百官的官员</li><li><strong>给事中</strong>：门下省官员，负责审核诏令</li><li><strong>校书郎</strong>：负责校对书籍的官员</li><li><strong>集贤殿学士</strong>：负责整理典籍的官员</li></ul><hr><p><em>注：本文约5400字，采用《大唐第一&quot;顶流&quot;：李白的职业经理人幻梦与谪仙之魂》的叙事风格，结合历史事实与文学想象，深度剖析杜甫从壮游少年到诗史巨匠的蜕变过程。</em></p>',125)])])}const d=o(p,[["render",i]]);export{g as __pageData,d as default};
